`timescale 1ns/1ps

// The grading testbench for milestone 3: the gate's priority rule, both
// counters, re-arming, and the detector underneath all of it.
module tb;

  localparam int W = 3;

  logic clk = 1'b0;
  always #5 clk = ~clk;

  logic rst_n = 1'b1;
  logic din   = 1'b0;
  logic arm   = 1'b0;
  logic found, missed;
  logic [W-1:0] count, missed_count;
  logic sat;

  logic [3:0] pattern = 4'b1011;

  seq_detect #(.W(W)) dut (
    .clk(clk), .rst_n(rst_n), .din(din), .pattern(pattern), .arm(arm),
    .found(found), .missed(missed),
    .count(count), .missed_count(missed_count), .sat(sat)
  );

  integer i;

  // One cycle, driving both inputs, so that "arm on the same cycle as
  // the detection" is a thing the testbench can actually express.
  task tick(input logic b, input logic a);
    begin
      @(negedge clk); din = b; arm = a;
      @(posedge clk); #1;
    end
  endtask

  task send(input logic b);
    begin
      tick(b, 1'b0);
    end
  endtask

  task arm_cycle;
    begin
      tick(1'b0, 1'b1);
    end
  endtask

  task reset;
    begin
      @(negedge clk); rst_n = 1'b0; din = 1'b0; arm = 1'b0;
      @(posedge clk); #1;
      rst_n = 1'b1;
    end
  endtask

  task stream(input integer n, input [31:0] bits);
    begin
      for (i = n - 1; i >= 0; i = i - 1) send(bits[i]);
    end
  endtask

  logic [W-1:0] c0, m0, c_shut, m_shut, c_one, m_one;
  logic [W-1:0] c_rearm, m_rearm, c_prio, m_prio, m_long;
  logic f_shut;

  initial begin
    $dumpfile("dump.vcd");
    $dumpvars(0, tb);

    reset();
    c0 = count;
    m0 = missed_count;

    // Shut throughout: four matches, all missed.
    reset();
    stream(18, 18'b101101101110101100);
    send(1'b0);
    c_shut = count;
    m_shut = missed_count;

    // And `found` never goes high.
    reset();
    stream(4, 4'b1011);
    f_shut = found;
    send(1'b0);

    // Armed once: the first passes, the other three are missed.
    reset();
    arm_cycle();
    stream(18, 18'b101101101110101100);
    send(1'b0);
    c_one = count;
    m_one = missed_count;

    // Re-armed between matches: both pass.
    reset();
    arm_cycle();
    stream(4, 4'b1011);
    send(1'b0);
    arm_cycle();
    stream(4, 4'b1011);
    send(1'b0);
    c_rearm = count;
    m_rearm = missed_count;

    // The priority rule. The detector's output is a Moore output, so
    // the match is visible during the cycle AFTER the last bit — and
    // that is the cycle the arm pulse has to land on.
    reset();
    arm_cycle();
    stream(4, 4'b1011);       // state is now the match state
    arm_cycle();              // match passes, and the gate is re-armed
    send(1'b1); send(1'b1);   // 1 1 after the 0 above completes it again
    send(1'b0);               // second match passes; the gate shuts
    send(1'b1); send(1'b1);
    send(1'b0);               // third match arrives shut
    c_prio = count;
    m_prio = missed_count;

    // Saturation reaches the missed counter too.
    reset();
    stream(32, 32'b10110110110110110110110110110110);
    send(1'b0);
    m_long = missed_count;

    $display("CHECK counters_start_at_zero 0 %0d AT %0d", c0, $time);
    $display("CHECK missed_starts_at_zero 0 %0d AT %0d", m0, $time);
    $display("CHECK shut_passes_nothing 0 %0d AT %0d", c_shut, $time);
    $display("CHECK shut_counts_every_match 4 %0d AT %0d", m_shut, $time);
    $display("CHECK found_low_while_shut 0 %0d AT %0d", f_shut, $time);
    $display("CHECK armed_passes_exactly_one 1 %0d AT %0d", c_one, $time);
    $display("CHECK and_misses_the_other_three 3 %0d AT %0d", m_one, $time);
    $display("CHECK rearming_passes_two 2 %0d AT %0d", c_rearm, $time);
    $display("CHECK rearming_misses_none 0 %0d AT %0d", m_rearm, $time);
    $display("CHECK arm_beats_self_disarm 2 %0d AT %0d", c_prio, $time);
    $display("CHECK and_the_third_is_missed 1 %0d AT %0d", m_prio, $time);
    $display("CHECK missed_saturates_too 7 %0d AT %0d", m_long, $time);
    $display("DONE 12");
    $finish;
  end

endmodule

