// A programmable four-bit pattern detector.
//
// The pattern is an input, not a constant, so there is no table to
// precompute: the last four bits are kept in a shift register and
// compared with it. `fill` is there to stop the register matching
// before four real bits have arrived.

module seq_match (
    input  logic       clk,
    input  logic       rst_n,     // synchronous, active low
    input  logic       din,       // one bit per clock
    input  logic [3:0] pattern,   // held steady; pattern[3] arrives first
    output logic       found      // registered: high for one cycle on a match
);

    logic [3:0] hist;    // the last four bits; hist[3] is the oldest
    logic [2:0] fill;    // bits received since reset, saturating at 4

    // What the shift register will hold after this edge.
    wire [3:0] next_hist = {hist[2:0], din};

    always_ff @(posedge clk) begin
        if (!rst_n) begin
            hist  <= 4'b0;
            fill  <= 3'd0;
            found <= 1'b0;
        end else begin
            hist  <= next_hist;
            if (fill != 3'd4) fill <= fill + 3'd1;
            // Three bits already in, plus the one arriving now.
            found <= (fill >= 3'd3) && (next_hist == pattern);
        end
    end

endmodule

// A saturating counter: it counts `inc` pulses and stops at its
// maximum rather than wrapping round to zero.

module det_counter #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         inc,
    output logic [W-1:0] count,
    output logic         sat
);

    // Saturated when every bit is set: one more pulse changes nothing.
    assign sat = &count;

    always_ff @(posedge clk) begin
        if (!rst_n)           count <= '0;
        else if (inc && !sat) count <= count + 1'b1;
    end

endmodule

// A one-shot arming gate.
//
// The gate holds one bit of state. A detection arriving while armed is
// passed on and shuts the gate behind it; a detection arriving while
// the gate is shut is reported as missed instead.

module arm_gate (
    input  logic clk,
    input  logic rst_n,       // synchronous, active low
    input  logic arm,         // a one-cycle pulse: arms the gate
    input  logic found_in,
    output logic found_out,   // found_in, while armed
    output logic missed       // found_in, while not armed
);

    logic armed;

    assign found_out = found_in &  armed;
    assign missed    = found_in & ~armed;

    // `arm` wins over the self-disarm, so a pulse on the same cycle as
    // a passed detection leaves the gate armed for the next one.
    always_ff @(posedge clk) begin
        if (!rst_n)                 armed <= 1'b0;
        else if (arm)               armed <= 1'b1;
        else if (found_in && armed) armed <= 1'b0;
    end

endmodule

// The top of milestone 3: the detector, the gate, and two counters --
// one for the detections that were let through and one for the
// detections that arrived while the gate was shut.
//
// Still no logic of its own. det_counter is instantiated twice, which
// is the reason it was made a module in the first place.

module seq_detect #(
    parameter int W = 4
) (
    input  logic         clk,
    input  logic         rst_n,
    input  logic         din,
    input  logic [3:0]   pattern,
    input  logic         arm,
    output logic         found,          // the gated detection
    output logic         missed,
    output logic [W-1:0] count,
    output logic [W-1:0] missed_count,
    output logic         sat             // the passed counter's saturation
);

    logic raw;

    seq_match u_match (
        .clk     (clk),
        .rst_n   (rst_n),
        .din     (din),
        .pattern (pattern),
        .found   (raw)
    );

    arm_gate u_gate (
        .clk       (clk),
        .rst_n     (rst_n),
        .arm       (arm),
        .found_in  (raw),
        .found_out (found),
        .missed    (missed)
    );

    det_counter #(.W(W)) u_count (
        .clk   (clk),
        .rst_n (rst_n),
        .inc   (found),
        .count (count),
        .sat   (sat)
    );

    det_counter #(.W(W)) u_missed (
        .clk   (clk),
        .rst_n (rst_n),
        .inc   (missed),
        .count (missed_count),
        .sat   ()
    );

endmodule
